set -u
echo "E5WRAP start $(date -u +%FT%TZ) gpu=$(nvidia-smi --query-gpu=name --format=csv,noheader 2>/dev/null) cpus=$(nproc)"
mkdir -p /root/e5
pip install -q uv 2>&1 | tail -1
uv venv -q -p 3.12 /root/e5/venv 2>&1 | tail -2
uv pip install -q --python /root/e5/venv/bin/python torch==2.5.1 --index-url https://download.pytorch.org/whl/cu124 2>&1 | tail -2
uv pip install -q --python /root/e5/venv/bin/python numpy safetensors 2>&1 | tail -2
echo '' | base64 -d | gunzip > /root/e5_bootstrap.sh
export E5_PHASES="setup build e5a_py pack" E5_RUNS=32 E5_SEED_SETS="900000" TORCH_COMPILE_DISABLE=1
bash /root/e5_bootstrap.sh > /root/e5.log 2>&1
grep '^E5RESULT' /root/e5.log | grep -E 'convert|phase'
PY=/root/e5/venv/bin/python; C=/root/e5/ironclad-v1-enc3.pt; cd /root/e5/spire-engine
run() { lbl=$1; shift; echo "L1D BEGIN $lbl $(date -u +%T)"; timeout 60m $PY python/search/search_eval.py $C --set runs --ascension 20 --runs 1024 --procs 3 --pass-rows 2048 --roots-per-call 128 "$@" > /root/l1d_$lbl.log 2>&1; echo "L1D END $lbl rc=$? $(date -u +%T)"; grep -E "^runs A20" /root/l1d_$lbl.log | sed "s/^/L1D $lbl: /" | cut -c1-500; }
# (1)-(3) sweep on the unseen seeds 900000+ (greedy there: 19.1%), (4) greedy + best-guess arm on a second fresh set 910000+
run boss_only   --seed-offset 600000 --no-baseline --search-rooms boss
run potion01    --seed-offset 600000 --no-baseline --potion-value 0.1
run eb_potion01 --seed-offset 600000 --no-baseline --search-rooms elite,boss --potion-value 0.1
run confirm_boss --seed-offset 610000 --search-rooms boss
run confirm_eb   --seed-offset 610000 --no-baseline --search-rooms elite,boss --potion-value 0.1
echo "E5WRAP summary end $(date -u +%FT%TZ)"
sleep 900
